content = 'import { createClient } from "https://esm.sh/@supabase/supabase-js@2";\n\nconst GROK_API_URL = "https://api.x.ai/v1/responses";\nconst MODEL = "grok-4.3";\n\n// ===== RAG helpers =====\n\nasync function generateEmbedding(text: string, apiKey: string): Promise<number[] | null> {\n  try {\n    const res = await fetch("https://api.openai.com/v1/embeddings", {\n      method: "POST",\n      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${apiKey}` },\n      body: JSON.stringify({ model: "text-embedding-3-small", input: text }),\n    });\n    if (!res.ok) return null;\n    const data = await res.json();\n    return data.data?.[0]?.embedding ?? null;\n  } catch {\n    return null;\n  }\n}\n\nasync function hybridSearch(\n  query: string,\n  supabase: ReturnType<typeof createClient>,\n  openaiKey: string,\n  limit = 6\n): Promise<string> {\n  const embedding = await generateEmbedding(query, openaiKey);\n  if (!embedding) return "";\n\n  const { data, error } = await supabase.rpc("search_treningi_hybrid", {\n    query_embedding: embedding,\n    query_text: query,\n    match_count: limit,\n  });\n\n  if (error || !data?.length) return "";\n\n  const { data: jData } = await supabase.from("jezdzcy").select("id, imie");\n  const { data: kData } = await supabase.from("konie").select("id, imie");\n  const jById: Record<string, string> = Object.fromEntries((jData || []).map((r: { id: string; imie: string }) => [r.id, r.imie]));\n  const kById: Record<string, string> = Object.fromEntries((kData || []).map((r: { id: string; imie: string }) => [r.id, r.imie]));\n\n  return (data as Record<string, unknown>[]).map((r) => {\n    return `[${r.data}] ${jById[r.jezdziec_id as string] || "?"} na ${kById[r.kon_id as string] || "\\u2014"}: ${r.cwiczenia || ""} | dobrze: ${r.dobrze || ""} | do poprawy: ${r.do_poprawy || ""} | ocena: ${r.ocena ?? "\\u2014"}`;\n  }).join("\\n");\n}\n\nconst corsHeaders = {\n  "Access-Control-Allow-Origin": "*",\n  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",\n};\n\nconst TOOLS = [\n  {\n    type: "function",\n    name: "szukaj_treningi",\n    description: "Semantycznie przeszukuje baz\\u0119 trening\\u00f3w za pomoc\\u0105 wyszukiwania hybrydowego (wektorowego + tekstowego). U\\u017cyj gdy szukasz konkretnych trening\\u00f3w po opisie, \\u0107wiczeniach, uwagach lub temacie.",\n    parameters: {\n      type: "object",\n      properties: {\n        zapytanie: { type: "string", description: "Opis szukanego treningu" },\n      },\n      required: ["zapytanie"],\n    },\n  },\n  {\n    type: "function",\n    name: "pobierz_treningi",\n    description: "Pobiera treningi z bazy danych dla podanego zakresu dat.",\n    parameters: {\n      type: "object",\n      properties: {\n        data_od: { type: "string", description: "Data pocz\\u0105tkowa YYYY-MM-DD" },\n        data_do: { type: "string", description: "Data ko\\u0144cowa YYYY-MM-DD" },\n        jezdziec: { type: "string", description: "Imi\\u0119 je\\u017ad\\u017aca (opcjonalnie)" },\n      },\n      required: ["data_od", "data_do"],\n    },\n  },\n  {\n    type: "function",\n    name: "pobierz_jezdzca",\n    description: "Pobiera pe\\u0142ny profil je\\u017ad\\u017aca wraz z ostatnimi 20 treningami.",\n    parameters: {\n      type: "object",\n      properties: {\n        imie: { type: "string", description: "Imi\\u0119 je\\u017ad\\u017aca" },\n      },\n      required: ["imie"],\n    },\n  },\n];\n\nasync function executeTool(\n  name: string,\n  args: Record<string, string>,\n  supabase: ReturnType<typeof createClient>,\n  openaiKey?: string\n): Promise<string> {\n  if (name === "szukaj_treningi") {\n    if (!openaiKey) return JSON.stringify({ error: "Brak OPENAI_API_KEY" });\n    const result = await hybridSearch(args.zapytanie || "", supabase, openaiKey, 10);\n    return result || JSON.stringify({ info: "Brak wynik\\u00f3w." });\n  }\n\n  if (name === "pobierz_treningi") {\n    const { data_od, data_do, jezdziec } = args;\n    const { data: jData } = await supabase.from("jezdzcy").select("id, imie");\n    const { data: kData } = await supabase.from("konie").select("id, imie");\n    const jById: Record<string, string> = Object.fromEntries((jData || []).map((r: { id: string; imie: string }) => [r.id, r.imie]));\n    const kById: Record<string, string> = Object.fromEntries((kData || []).map((r: { id: string; imie: string }) => [r.id, r.imie]));\n    let query = supabase.from("treningi").select("*").gte("data", data_od).lte("data", data_do).order("data", { ascending: false });\n    if (jezdziec) {\n      const jezdziecId = Object.entries(jById).find(([, v]) => v.toLowerCase() === jezdziec.toLowerCase())?.[0];\n      if (jezdziecId) query = query.eq("jezdziec_id", jezdziecId);\n    }\n    const { data, error } = await query;\n    if (error) return JSON.stringify({ error: error.message });\n    return JSON.stringify((data || []).map((r: Record<string, unknown>) => ({\n      data: r.data, jezdziec: jById[r.jezdziec_id as string] || "?", kon: kById[r.kon_id as string] || "\\u2014",\n      typ: r.typ_jazdy || "plac", grupowa: r.grupowa, cwiczenia: r.cwiczenia,\n      uwagi: r.uwagi, dobrze: r.dobrze, do_poprawy: r.do_poprawy, ocena: r.ocena,\n    })));\n  }\n\n  if (name === "pobierz_jezdzca") {\n    const { imie } = args;\n    const { data: jData } = await supabase.from("jezdzcy").select("*").ilike("imie", imie).single();\n    if (!jData) return JSON.stringify({ error: `Nie znaleziono je\\u017ad\\u017aca: ${imie}` });\n    const { data: kData } = await supabase.from("konie").select("id, imie");\n    const kById: Record<string, string> = Object.fromEntries((kData || []).map((r: { id: string; imie: string }) => [r.id, r.imie]));\n    const { data: treningi } = await supabase.from("treningi").select("*").eq("jezdziec_id", jData.id).order("data", { ascending: false }).limit(20);\n    return JSON.stringify({\n      imie: jData.imie, poziom: jData.poziom, jezdzi_od: jData.jezdzi_od,\n      umiejetnosci: jData.umiejetnosci, do_poprawy: jData.do_poprawy,\n      postawa: jData.postawa, preferencje: jData.preferencje, notatki: jData.notatki,\n      ostatnie_treningi: (treningi || []).map((r: Record<string, unknown>) => ({\n        data: r.data, kon: kById[r.kon_id as string] || "\\u2014", typ: r.typ_jazdy,\n        cwiczenia: r.cwiczenia, uwagi: r.uwagi, dobrze: r.dobrze, do_poprawy: r.do_poprawy, ocena: r.ocena,\n      })),\n    });\n  }\n\n  return JSON.stringify({ error: `Nieznany tool: ${name}` });\n}\n\nfunction buildSystemPrompt(context: {\n  selDay: string; treningiDnia: unknown[]; jezdzcy: unknown[]; konie: unknown[];\n}, ragContext?: string): string {\n  const dzienNazwa = new Date(context.selDay).toLocaleDateString("pl-PL", {\n    weekday: "long", year: "numeric", month: "long", day: "numeric",\n  });\n  return `Jeste\\u015b Cwa\\u0142ek \\u2014 wirtualny asystent stajni. Pomagasz instruktorowi jazdy konnej prowadzi\\u0107 dziennik trening\\u00f3w.\n\nTw\\u00f3j charakter:\n- Ciep\\u0142y, konkretny, z nutk\\u0105 humoru \\u2014 ale zawsze na temat\n- Odpowiadasz po polsku, kr\\u00f3tko i tre\\u015bciwie (2\\u20135 zda\\u0144)\n- Gdy potrzebujesz danych spoza bie\\u017c\\u0105cego dnia, u\\u017cywasz narz\\u0119dzi\n- Nie wymyslasz danych\n\nBIE\\u017b\\u0104CY DZIE\\u0143: ${context.selDay} (${dzienNazwa})\n\nTRENINGI BIE\\u017b\\u0104CEGO DNIA:\n${context.treningiDnia.length ? JSON.stringify(context.treningiDnia, null, 2) : "Brak trening\\u00f3w w tym dniu."}\n\nJE\\u0179D\\u0179CY: ${JSON.stringify((context.jezdzcy as Array<{imie?:string;poziom?:string}>).map(j=>({imie:(j as {imie?:string}).imie,poziom:(j as {poziom?:string}).poziom})))}\n\nKONIE: ${JSON.stringify((context.konie as Array<{imie?:string;typ?:string}>).map(k=>({imie:(k as {imie?:string}).imie,typ:(k as {typ?:string}).typ})))}\n\nJe\\u015bli pytanie dotyczy historii, u\\u017cyj pobierz_treningi lub pobierz_jezdzca.\nJe\\u015bli szukasz trening\\u00f3w po tematyce, u\\u017cyj szukaj_treningi.\n${ragContext ? \\`\n---\nPASUJ\\u0104CE WPISY Z BAZY (wyszukiwanie hybrydowe):\n${ragContext}\n---\n\\` : ""}`;\n}\n\nDeno.serve(async (req: Request) => {\n  if (req.method === "OPTIONS") {\n    return new Response("ok", { headers: corsHeaders });\n  }\n\n  try {\n    const grokKey = Deno.env.get("GROK_API_KEY");\n    const openaiKey = Deno.env.get("OPENAI_API_KEY");\n    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;\n    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;\n\n    if (!grokKey) {\n      return new Response(JSON.stringify({ error: "Brak klucza GROK_API_KEY" }), {\n        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },\n      });\n    }\n\n    const anonKey = Deno.env.get("SUPABASE_ANON_KEY");\n    const reqApiKey = req.headers.get("apikey") || req.headers.get("x-api-key") || "";\n    if (anonKey && reqApiKey !== anonKey) {\n      return new Response(JSON.stringify({ error: "Nieautoryzowany dost\\u0119p." }), {\n        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },\n      });\n    }\n\n    const supabase = createClient(supabaseUrl, supabaseKey);\n    const body = await req.json();\n    const { messages, context } = body;\n\n    const lastUserMsg = [...(messages || [])].reverse().find((m: { role: string }) => m.role === "user");\n    const lastUserText = typeof lastUserMsg?.content === "string" ? lastUserMsg.content : "";\n    let ragContext = "";\n    if (openaiKey && lastUserText) {\n      ragContext = await hybridSearch(lastUserText, supabase, openaiKey, 6);\n    }\n\n    const systemPrompt = buildSystemPrompt(context, ragContext);\n    const input: unknown[] = [{ role: "system", content: systemPrompt }, ...messages];\n    let previousResponseId: string | undefined;\n    let currentInput = input;\n    let finalText = "";\n\n    for (let i = 0; i < 5; i++) {\n      const reqBody: Record<string, unknown> = { model: MODEL, input: currentInput, tools: TOOLS };\n      if (previousResponseId) reqBody.previous_response_id = previousResponseId;\n\n      const grokRes = await fetch(GROK_API_URL, {\n        method: "POST",\n        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${grokKey}` },\n        body: JSON.stringify(reqBody),\n      });\n\n      if (!grokRes.ok) {\n        const err = await grokRes.text();\n        return new Response(JSON.stringify({ error: `Grok API error: ${err}` }), {\n          status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },\n        });\n      }\n\n      const data = await grokRes.json();\n      previousResponseId = data.id;\n      const toolCalls = (data.output || []).filter((o: { type: string }) => o.type === "function_call");\n      const messageOutput = (data.output || []).find((o: { type: string }) => o.type === "message");\n      if (messageOutput) finalText = messageOutput.content?.[0]?.text || "";\n      if (toolCalls.length === 0) break;\n\n      const toolResults: unknown[] = [];\n      for (const tc of toolCalls) {\n        const args = JSON.parse(tc.arguments || "{}");\n        const result = await executeTool(tc.name, args, supabase, openaiKey);\n        toolResults.push({ type: "function_call_output", call_id: tc.call_id, output: result });\n      }\n      currentInput = toolResults;\n    }\n\n    return new Response(JSON.stringify({ reply: finalText }), {\n      headers: { ...corsHeaders, "Content-Type": "application/json" },\n    });\n  } catch (err) {\n    return new Response(JSON.stringify({ error: String(err) }), {\n      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },\n    });\n  }\n});\n'

